<template>
  <section class="page-stack wide-workspace"><header class="page-heading"><span class="kicker">Calibration</span><h1>校准与晋级工作台</h1><p>显式管理数据集、独立标注、裁决、校准运行和 metric registry。工程晋级不等于临床有效性。</p></header>
    <div class="panel-grid two"><form class="form-panel compact-form" @submit.prevent="createDataset"><h2>创建数据集</h2><label>名称<input v-model="newDataset.name" required /></label><label>版本<input v-model="newDataset.version" required /></label><label>说明<textarea v-model="newDataset.description" /></label><button class="primary-button">创建</button></form><form class="form-panel compact-form" @submit.prevent="loadDataset"><h2>打开数据集</h2><label>Dataset ID<input v-model="datasetId" required /></label><button class="secondary-button">加载</button><p class="muted">当前后端未提供数据集列表接口，因此使用真实 ID 定位，不展示虚构列表。</p></form></div>
    <p v-if="error" class="inline-notice danger" role="alert">{{ error }}</p><p v-if="notice" class="inline-notice" role="status">{{ notice }}</p>
    <section v-if="dataset" class="workspace-panel"><div class="section-heading"><div><h2>{{ dataset.name }}</h2><p>{{ dataset.version }} · {{ dataset.sample_count }} samples</p></div><StatusBadge :status="dataset.status" /></div><div class="summary-strip"><div><small>Dataset ID</small><strong>{{ dataset.id }}</strong></div><div><small>冻结时间</small><strong>{{ formatDateTime(dataset.frozen_at) }}</strong></div></div><div class="action-row"><button class="secondary-button" :disabled="dataset.status!=='draft'" @click="showSample=!showSample">添加 sample</button><button class="secondary-button danger" :disabled="dataset.status!=='draft'" @click="confirmFreeze=true">冻结数据集</button></div><form v-if="showSample" class="compact-form inline-form" @submit.prevent="addSample"><label>EvaluationRun ID<input v-model="evaluationRunId" required /></label><label>Dimension code<input v-model="dimensionCode" required /></label><button class="primary-button">添加</button></form><ul class="plain-list"><li v-for="id in dataset.sample_ids" :key="id"><code>{{ id }}</code><button class="text-button" :disabled="dataset.status!=='draft'" @click="removeSample(id)">移除</button></li></ul></section>
    <div class="panel-grid two"><form class="form-panel compact-form" @submit.prevent="submitAnnotation(false)"><h2>独立标注</h2><label>Sample ID<input v-model="annotation.sample_id" required /></label><label>Dimension<input v-model="annotation.dimension_code" required /></label><div class="form-grid"><label>值<input v-model.number="annotation.value" type="number" step="any" /></label><label>单位<input v-model="annotation.unit" /></label></div><label>备注<textarea v-model="annotation.comment" /></label><button class="primary-button">提交标注</button></form><form class="form-panel compact-form" @submit.prevent="submitAnnotation(true)"><h2>裁决结果</h2><p class="muted">仅在双标流程需要裁决时使用；提交将写入 adjudicated reference。</p><label>Sample ID<input v-model="adjudication.sample_id" required /></label><label>Dimension<input v-model="adjudication.dimension_code" required /></label><div class="form-grid"><label>裁决值<input v-model.number="adjudication.value" type="number" step="any" /></label><label>单位<input v-model="adjudication.unit" /></label></div><label>裁决说明<textarea v-model="adjudication.comment" required /></label><button class="secondary-button">提交裁决</button></form></div>
    <div class="panel-grid two"><form class="form-panel compact-form" @submit.prevent="loadMetric"><h2>Metric registry</h2><label>Metric code<input v-model="metricCode" required /></label><button class="secondary-button">查询</button><div v-if="metric"><StatusBadge :status="metric.status"/><JsonDetails :value="metricObject" /></div></form><form class="form-panel compact-form" @submit.prevent="runCalibration"><h2>运行校准</h2><label>冻结 Dataset ID<input v-model="runDatasetId" required /></label><label>Metric code<input v-model="runMetricCode" required /></label><button class="primary-button">Run Calibration</button><p class="muted">只在点击后执行，不会随页面加载自动运行。</p></form></div>
    <article v-if="report" class="surface-card"><h2>Calibration report</h2><StatusBadge :status="String(report.promotion.decision||'review_required')"/><div class="panel-grid two"><div><h3>Development</h3><JsonDetails :value="report.development"/></div><div><h3>Holdout</h3><JsonDetails :value="report.holdout"/></div></div><h3>Subgroups / reference quality</h3><JsonDetails :value="report.subgroups"/><JsonDetails :value="report.human_reference_quality"/><ul><li v-for="x in report.limitations" :key="x">{{ x }}</li></ul></article>
    <ConfirmDialog :open="confirmFreeze" title="冻结校准数据集？" message="冻结后不能添加或移除样本。校准运行只接受冻结数据集。" confirm-label="确认冻结" danger @cancel="confirmFreeze=false" @confirm="freeze" />
  </section>
</template>
<script setup lang="ts">
import { computed,ref } from 'vue'; import { calibrationApi } from '@/api/calibration'; import ConfirmDialog from '@/components/common/ConfirmDialog.vue'; import JsonDetails from '@/components/common/JsonDetails.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import { formatDateTime } from '@/utils/date'; import type { CalibrationDataset,CalibrationReport,JsonObject,MetricRegistry } from '@/types/professional'
const datasetId=ref(''),dataset=ref<CalibrationDataset|null>(null),error=ref(''),notice=ref(''),confirmFreeze=ref(false),showSample=ref(false),evaluationRunId=ref(''),dimensionCode=ref(''),newDataset=ref({name:'',version:'',description:''}); const annotation=ref({sample_id:'',dimension_code:'',value:null as number|null,unit:'',comment:'',annotation_round:1}),adjudication=ref({...annotation.value}); const metricCode=ref(''),metric=ref<MetricRegistry|null>(null),runDatasetId=ref(''),runMetricCode=ref(''),report=ref<CalibrationReport|null>(null); const metricObject=computed(()=>metric.value as unknown as JsonObject)
function msg(e:unknown){return e instanceof Error?e.message:'操作失败'} async function createDataset(){try{const r=await calibrationApi.createDataset(newDataset.value);datasetId.value=r.id;await loadDataset();notice.value='数据集已创建。'}catch(e){error.value=msg(e)}} async function loadDataset(){try{dataset.value=await calibrationApi.dataset(datasetId.value);runDatasetId.value=datasetId.value;error.value=''}catch(e){error.value=msg(e)}} async function addSample(){try{await calibrationApi.addSample(datasetId.value,evaluationRunId.value,dimensionCode.value);await loadDataset()}catch(e){error.value=msg(e)}} async function removeSample(id:string){try{await calibrationApi.removeSample(datasetId.value,id);await loadDataset()}catch(e){error.value=msg(e)}} async function freeze(){try{await calibrationApi.freeze(datasetId.value);confirmFreeze.value=false;await loadDataset()}catch(e){error.value=msg(e)}} async function submitAnnotation(isAdjudication:boolean){try{const data=(isAdjudication?adjudication.value:annotation.value) as unknown as JsonObject;if(isAdjudication)await calibrationApi.adjudicate(data);else await calibrationApi.annotate(data);notice.value=isAdjudication?'裁决结果已保存。':'独立标注已保存。'}catch(e){error.value=msg(e)}} async function loadMetric(){try{metric.value=await calibrationApi.metric(metricCode.value);runMetricCode.value=metricCode.value}catch(e){error.value=msg(e)}} async function runCalibration(){try{const r=await calibrationApi.run(runDatasetId.value,runMetricCode.value);report.value=await calibrationApi.report(r.id);notice.value='校准运行完成。'}catch(e){error.value=msg(e)}}
</script>
